@Service
public class IsolatedSearchClient {
    private final ThreadPoolBulkhead bulkhead;

    public IsolatedSearchClient(ThreadPoolBulkheadRegistry registry) {
        ThreadPoolBulkheadConfig config = ThreadPoolBulkheadConfig.custom()
            .maxThreadPoolSize(15)
            .coreThreadPoolSize(10)
            .queueCapacity(20)
            .keepAliveDuration(Duration.ofMillis(50))
            .build();
        this.bulkhead = registry.bulkhead("searchBulkhead", config);
    }

    public CompletableFuture<SearchResult> executeSearch(String query) {
        return ThreadPoolBulkhead.executeSupplier(bulkhead, () -> performSearch(query))
            .exceptionally(ex -> {
                // Fast-fail fallback when pool is saturated
                return SearchResult.empty("Search temporarily unavailable due to high load");
            });
    }
}
